SELECT u.user_id, MAX(CASE WHEN r.role_code IN ('author', 'admin') THEN 1 ELSE 0 END) AS site_author, MAX(CASE WHEN r.role_code = 'admin' THEN 1 ELSE 0 END) AS site_admin FROM sys_user u JOIN sys_user_role ur ON ur.user_id = u.user_id JOIN sys_role r ON r.role_id = ur.role_id WHERE u.status = 1 AND r.status = 1 AND r.role_code IN ('author', 'admin') AND u.user_id IN
#{id}
GROUP BY u.user_id
